Here's a simple C++ program that computes the nth Fibonacci number using naive recursion (fib(0)=0, fib(1)=1). Note: this approach is exponential in time and not efficient for large n.

```cpp
#include <iostream>

long long fib(int n) {
    if (n <= 1) return n;
    return fib(n - 1) + fib(n - 2);
}

int main() {
    int n;
    std::cout << "Enter n (non-negative): ";
    if (!(std::cin >> n) || n < 0) {
        std::cerr << "Invalid input. Please enter a non-negative integer.\n";
        return 1;
    }

    std::cout << "Fibonacci(" << n << ") = " << fib(n) << std::endl;
    return 0;
}
```

