Here’s a C++ program that computes the nth term of the sequence defined by:
t0 = 0, t1 = -1, t2 = -1, and t_n = t_{n-1} + t_{n-2} + t_{n-3} for n >= 3.
It uses an iterative approach (O(n) time, O(1) space) with 0-based indexing.

```cpp
#include <iostream>

long long tribonacci(int n) {
    if (n == 0) return 0;
    if (n == 1) return -1;
    if (n == 2) return -1;

    long long t0 = 0;   // t0
    long long t1 = -1;  // t1
    long long t2 = -1;  // t2

    for (int i = 3; i <= n; ++i) {
        long long t3 = t0 + t1 + t2; // t_i = t_{i-1} + t_{i-2} + t_{i-3}
        t0 = t1;
        t1 = t2;
        t2 = t3;
    }
    return t2;
}

int main() {
    int n;
    std::cout << "Enter n (0-based index, n >= 0): ";
    if (!(std::cin >> n) || n < 0) {
        std::cerr << "Invalid input. Please enter a non-negative integer.\n";
        return 1;
    }

    std::cout << "a[" << n << "] = " << tribonacci(n) << std::endl;
    return 0;
}
```

Note:
- This uses 0-based indexing: a[0] = 0, a[1] = -1, a[2] = -1.
- If you prefer 1-based indexing, you can adjust accordingly (e.g., define a[1]=0, a[2]=-1, a[3]=-1 and compute from there).

