Here's a C++17 implementation that prints all common elements including duplicates (multiplicity is min(count in A, count in B)):

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n)) return 0;
    if (!(cin >> m)) return 0;

    vector<long long> a(n), b(m);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int j = 0; j < m; ++j) cin >> b[j];

    // Count frequencies in the first array
    unordered_map<long long, int> freq;
    freq.reserve(n * 2); // avoid rehashing
    for (const auto& x : a) ++freq[x];

    // Emit common elements with multiplicity min(freq in A, occurrences in B)
    bool first = true;
    for (const auto& x : b) {
        auto it = freq.find(x);
        if (it != freq.end() && it->second > 0) {
            if (!first) cout << ' ';
            cout << x;
            first = false;
            --(it->second);
        }
    }
    cout << '\n';
    return 0;
}
```

Notes:
- Time complexity: average O(n + m) due to hashing (insertion + lookup).
- Space complexity: O(n) for the frequency map (worst-case, equals number of distinct elements in the first array).
- If you want only unique common elements, you can insert elements of the first array into an unordered_set and then build another set for the result, printing the result set at the end (still O(n + m) time, with additional O(k) space for k unique common elements). If you’d like, I can provide that variant too.

